\section{Preliminaries}
\label{sect:Preliminaries}

Throughout the paper, all graphs are undirected unless specified to be directed. 

We always use $n$ and $m$ to denote the number of vertices and edges of the original graph in the context (for example, the original graph of each main theorem is its input graph). For a real function $F:D\to \bbR$ and $S\subseteq D$, we write $F(S)=\sum_{s\in S}F(s)$. 

\paragraph{Polynomially-Bounded Integral Functions and Positive Lengths and Capacities.}
Original graphs might have length, capacities, demands, node-weightings, etc, and we assume that all these values (which could be real numbers), after scaling up to integers, are upper bounded by a parameter denoted as $N$. We assume $N=\poly(n)$. 

Especially, we assume that all length and capacities are \emph{positive} integers.

\paragraph{Undirected graphs with vertex lengths and capacities.}
A undirected graph with vertex lengths and capacities, denoted by $G=(V,E)$ is an undirected graph where each vertex is associated with a length and a capacity from $\mathbb{N}^+$. We define the length function $\ell:V\to \mathbb{N}^{+}$ and the capacity function $U:V\to \mathbb{N}^{+}$ as mapping a vertex to its associated vertex length and capacity. We use $\ell_G,U_G$ to emphasize they are the length and capacity function for $G$. We use $V(G),E(G)$ to denote the vertex and edge set of $G$.

For convenience, we will not assign lengths and capacities to edges for such graphs. Namely, each edge has length $0$ and infinite capacity. This is without loss of generality because we can always transform edge lengths and capacities into vertex lengths and capacities by putting a vertex on each edge (and our work and depth bound are not sensitive to number of vertices).

\paragraph{Basic graph terminologies.} We define $\delta_G(u)=\{(u,v)\in E\}$ to be all adjacent edges of $u$ in $G$. We can extend this definition to $\delta_H(u)=\{(u,v)\in H\}$ where $H\subseteq E$ is an edge subset (or a subgraph). We use $N_G(u)$ to denote the vertex set of the neighborhood of $u$. We write $N_G(S)=\cup_{v\in S}N_G(v)-S$. We write $N_G[v]=N_G(v)\cup \{v\}$ and $N_G[S]=N_G(S)\cup S$. 

\paragraph{Path and distances.} 
A simple path $P$ in $G$ is a sequence of distinct vertices $(v_1,...,v_k)$ such that $(v_i,v_{i+1})\in E$ for every $i\in[k-1]$.  We define $\step(P)=k$.We define $V(P)=\{v_1,...,v_k\}$, $E(P)=\{(v_i,v_{i+1})\in E\mid i\in[k-1]\}$, and $\Start(P)=v_1,\End(P)=v_k$. We define $\Succ_P(v_i)=v_{i+1}$ and $\Prec_P(v_i)=v_{i-1}$. 
For two vertices $v_i,v_j\in V(P)$ with $i\le j$, we define $P[v_i,v_j]$ as the subpath $\{v_i,v_{i+1},...,v_j\}$. Notice that $E(P)$ only contains undirected edges, if we want to emphasis the path direction, we use $\vec{E}(P)$ to denote the set of ordered pairs $(v_i,v_{i+1})$ for $i\in[k-1]$.

We define the length of the path $P$ as $\ell(P) = \ell(V(P))$(also denoted by $\leng(P)$), and its step $|P|$ as the number of edges in $E(P)$. When we want to emphasize that $\leng(P)$ is with respect to $G$, we will write $\leng(P)$ as $\leng(P,G)$.
We define $\dist_G(u,v)$ as the minimum length of simple paths from $u$ to $v$. We define $\dist_G(S,T)$ for two vertex sets $S,T$ as $\min_{s\in S,t\in T}\dist_G(s,t)$. We say $S,T$ are $h$-far if $\dist_G(S,T)\ge h$. We define the \emph{diameter} of $S$ as $\max_{u,v\in S}\dist_G(u,v)$. When $G$ is clear from the context, we omit $G$ from the subscript.

\subsection{Flows and Demands}
\label{sect:PrelimFlow}

\paragraph{(Multicommodity) Flows.} A (multicommodity) \emph{flow} $F$ in $G$ is a function that assigns to each (directed) simple path $P$ in $G$ a flow value $F(P)\in\bbR_{\ge 0}$. A path $P$ is a \emph{flow path} of $F$ if $F(P)>0$, and we use $\path(F)$ to denote the set of all flow paths of $F$. Without ambiguity, each flow path $P\in\path(F)$ is also a multicommodity flow (which has only one flow path $P$ with value $F(P)$) and all the notations below can apply on $P$. The value of $F$ is $\vvalue(F) = \sum_{P\in\path(F)} F(P)$. 
We have the following parameters for a flow $F$.
\begin{itemize}
    \item \emph{Length}: The length of $F$ is $\leng(F) = \max_{P\in\path(F)}\leng(P)$, and again we write $\leng(F)$ as $\leng(F,G)$ to emphasize that it is with respect to $G$. We say $F$ is an $h$-length flow if $\leng(F)\leq h$. 
    \item \emph{Step}: The step of $F$ is $\step(F) = \max_{P\in\path(F)}\step(P)$. 
    \item \emph{Congestion}: For each vertex $v \in V(G)$, the amount of \emph{flow units} allocated on $v$ by $F$ is $F(v) = \sum_{v\in V(P),P\in\path(F)} F(P)$.
The congestion of $F$ is $\cong(F) = \max_{v\in V(G)}F(v)/U(v)$. 
\end{itemize}

For a flow path $P\in \path(F)$, a \emph{flow subpath} $\hat{P}$ of $P$ is a subpath of $P$, and $\hat{P}$ also represents a multicommodity flow which has only one flow path $\hat{P}$ with value $\vvalue(P)$. A flow $F'$ is a \emph{subflow} of $F$ if $F'(P)\leq F(P)$ for each simple path $P$. Given two flows $F_{1}$ and $F_{2}$, $F_{1}+F_{2}$ denotes the flow where $(F_{1}+F_{2})(P) = F_{1}(P) + F_{2}(P)$ for each simple path $P$.

A \emph{path representation} of a flow represents the flow by storing all its flow paths and associated values. For \emph{edge representation}, we define $\vec{E}$ to be the directed counterpart of $E$, i.e. we put two opposite directed edges into $\vec{E}$ for each edge in $E$. The \emph{edge representation} of a flow $F$ is representing the flow by storing $F(e)$ for every edge $e\in \vec{E}$, where 
\[
F(e) = \sum_{P\in\path(F),\vec{E}(P)\ni e} F(P).
\]
Note that a flow path $P$ has a direction, and we use $\vec{E}(P)$ denote the directed edges on $P$ consistent with $P$'s direction.

\medskip\noindent{\textbf{(Multi-Commodity) Demands.}}
A \emph{demand} $D:V\times V\rightarrow\mathbb{R}_{\ge0}$ assigns
a non-negative value $D(v,w) \ge 0$ to each ordered pair of vertices in $V$ to specify the units of demand $D(v,w)$ vertex $v$ wants to send to vertex $w$. We note that it is always safe to assume $D(u,u) = 0$.
The size of a demand is written as $|D|$ and is defined as $\sum_{v,w} D(v,w)$. The \emph{support} of the demand $D$ is defined as $\supp(D)=\{u,v\in V\mid D(u,v)>0\}$. For each vertex $v$, we let $D(v,\cdot) = \sum_{w}D(v,w)$ and $D(\cdot,v) = \sum_{w}D(w,v)$ denote the total demand starting and ending at $v$ respectively. 
The vertex set of $D$, denoted by $V(D)$, is the set of all vertices $v$ with $D(v,\cdot)>0$ or $D(\cdot,v)>0$. 
We say a demand $D$ is
\begin{itemize}
    \item \emph{h-length constrained}: if for each $v,w \in V$ with $D(v,w) > 0$, we have $\dist_G(v,w) \le h$;
    \item \emph{sub-demand for $D'$}: if for any pairs of $v,w \in V$, $D(v,w) \le D'(v,w)$;
    \item \emph{$A$-respecting for some node-weighting $A$}: if for any $v\in V$, $\max\{D(v,\cdot),D(\cdot,v)\}\leq A(v)$;
\end{itemize}

For a flow $F$, the demand routed by/corresponding to $F$ is denoted by $\Dem(F)$ or $D_{F}$, where for each $u,v\in V(G)$, $D_{F}(u,v) = \sum_{P\in\path(F)~\text{s.t. $P$ is a $(u,v)$-path}} F(P)$.
We say a demand $D$ is routable with length $h$, congestion $\gamma$ and step $t$ if there is a flow $F$ routing $D$ with length $h$, congestion $\gamma$ and step $t$.

\subsection{Neighborhood covers.} 
\begin{definition}[Neighborhood covers]\label{def:neicov}
    Given a graph $G=(V,E)$ with vertex length, a \emph{neighborhood cover} $\cN$ is a collection of sets called \emph{clusterings} $\cS_1,...,\cS_\omega$ where each $\cS_i$ contains vertex disjoint subsets of $V$, we care about the following parameters of a neighborhood cover.
    \begin{enumerate}
        \item \textbf{Covering radius $h_{\cov}$:} Every subset $A\subseteq V$ with diameter at most $h_{cov}$ is a subset of some $S\in\cS_i$ for some $i$.
        \item \textbf{Diameter $h_{\diam}$:} For every $i$ and every $S\in\cS_i$, $S$ has diameter at most $h_{\diam}$.
        \item \textbf{Separation-factor $s$:} For every $i$, every two different sets in $\cS_i$ are $\left(s\cdot h_{\diam}\right)$-far.
        \item \textbf{Width:} the number of clustering, denoted by $w$.
    \end{enumerate}
\end{definition}

\begin{theorem}\label{thm:neicov}
    There exists an algorithm that is given a graph $G$ with vertex lengths, parameters $h_{\cov},s>1$ and $\eps\in(0,1)$, output a neighborhood cover with covering radius $h_{\cov}$, separation-factor $s$, diameter and width
    \[h_{\diam}=\frac{1}{\eps}\cdot O(s)^{O(1/\eps)}\cdot h_{\cov}\qquad \qquad \omega=n^{O(\eps)}\cdot \log n\]
    in $h_{\diam}\cdot n^{O(\eps)}$ depth and $m\cdot h_{\diam}\cdot n^{O(\eps)}$ work with high probability. 
\end{theorem}

\subsection{Length-Constrained Vertex Expander Decomposition}\label{subsec:preliminaryexpander}

\paragraph{Node-Weightings}
A \emph{node-weighting} $A:V\rightarrow\mathbb{R}_{\ge0}$ assigns a non-negative value $A(v)$ to a vertex $v$. The \emph{size} of $A$ is denoted by $|A|=\sum_{v}A(v)$ and let $\supp(A) := \{v : A(v) > 0\}$. For two node-weightings $A,A'$ we define $\min(A,A')$
and $A+A'$ as pointwise operations, and we write $A \preceq A'$ if $A$ is pointwise at most $A'$. We say $A$ restricting to a vertex set $S$ (denoted by $A_S$) as another node-weighting which assigns the same weight on every vertex in $S$ as $A$, and $0$ weight for every other vertices.

For a demand $D$ and a node-weighting $A$, we say $D$ is $A$-respecting if for each vertex $v$, $D(v,\cdot) + D(\cdot,v)\leq A(v)$.
For a flow $F$, We say $F$ routes $A$ to $B$ for some node-weightings $A,B$ with $|A|=|B|$ if $F$ routes a demand $D$ with $D(v,\cdot)=A(v)$ and $D(\cdot,v)=B(v)$.

\paragraph{Vertex Moving Cuts.} 

An $h$-length (moving) cut $C: V \rightarrow \{0, \frac{1}{h}, \frac{2}{h},\ldots\}$ on a graph $G$ assigns to each vertex $v$ a fractional cut value which is a multiple of $\frac{1}{h}$. The size of $C$ is defined as $|C| =\sum_{v}U_G(v)\cdot C(v)$. 
The length increase associated with the $h$-length moving cut $C$ is defined as $\l_{C,h}(v) = h \cdot C(v)$. 

\begin{definition}
    For a graph $G$ with length function $\l$ we define $G - C$ (or $G+\l_{C,h}(v)$) as the graph with an updated length function $\l_{G-C}$ which assigns each vertex $v$ the length $\l_{G-C}(v) = \l(v) + \l_{C,h}(v)$.
\end{definition}
\begin{definition}[$h$-Length Separated Demand]
    For any $h$-length moving cut $C$ and demand $D$ on graph $G$, we define the amount of $h$-length separated demand as the sum of demands between vertices that are $h$-length separated by $C$. We denote this quantity with $\sep_h(C,D)$, i.e.,
    \begin{align*}
        \sep_{h}(C,D) = \sum_{u,v : \dist_{G-C}(u,v)>h} D(u,v).
    \end{align*}
\end{definition}

\begin{remark}
    In the notation of $\sep_h(C,D)$, we hide the inherent graph $G$ where the cut $C$ and demand $D$ is on. When using the definition, we assume we are working on the graph $G$ where $C$ and $D$ are defined. When we want to emphasize it is on a specific graph $G$, we will add it in the subscript. The same simplification applies to the rest of the definitions.
\end{remark}

\begin{definition}[$h$-Length Sparsity of a Cut $C$ for Demand $D$]\label{dfn:CDSparse}
For any demand $D$ and any $h$-length moving cut $C$ on graph $G$ with $\sep_{h}(C,D)>0$, the $h$-length sparsity of $C$ with respect to $D$ is the ratio of $C$'s size to how much demand it $h$-length separates i.e.,
\begin{align*}
    \spa_{h}(C,D) = \frac{|C|}{\sep_{h}(C,D)}.
\end{align*}
\end{definition}

\begin{definition}[$(h,s)$-Length Sparsity of a Cut w.r.t.\ a Node-Weighting]\label{def:sparsity}
The $(h,s)$-length sparsity of any $h\cdot s$-length moving cut $C$ with respect to a node-weighting $A$ is defined as:
\begin{align*}
    \spa_{(h,s)}(C,A) = \min_{A\text{-respecting h-length demand}\ D} \spa_{h \cdot s} (C,D).
\end{align*}

We say $C$ is an $(h,s)$-length $\phi$-sparse cut (with respect to $A$ on $G$) if $\spa_{(h,s)}(C,A)\le \phi$.
\end{definition}

\begin{definition}[$(h,s)$-Length Conductance of a Node-Weighting]
    The $(h,s)$-length conductance of a node-weighting $A$ in a graph $G$ is defined as the $(h,s)$-length sparsity of the sparsest $h\cdot s$-length moving cut $C$ with respect to $A$, i.e.,
    \begin{align*}
        \cond_{(h,s)}(A) = \min_{h \cdot s\text{-length moving cut } C} \spa_{(h,s)}(C,A).
    \end{align*}
\end{definition}

\begin{definition}[$(h,s)$-Length $\phi$-Expanding Node-Weightings]\label{def:LC directed expansion}
    We say a node-weighting $A$ is $(h,s)$-length $\phi$-expanding if the $(h,s)$-length conductance of $A$ in $G$ is at least $\phi$.
\end{definition}

\begin{theorem}[Routing Characterization of Length-Constrained Expanders, \cite{HaeuplerLSW25}]\label{thm:flow character} Given graph $G$ with vertex lengths and capacities and a node-weighting $A$, for any $h \geq 1$, $\phi < 1$ and $s \geq 1$ we have:
\begin{itemize}
\item \textbf{Length-Constrained Expanders Have Good Routings} If $A$ is $(h,s)$-length $\phi$-expanding in $G$, then every $h$-length $A$-respecting demand can be routed in $G$ with congestion at most $O(\frac{\log n}{\phi})$ and dilation at most $h\cdot s$.
\item \textbf{Not Length-Constrained Expanders Have a Bad Demand} If $A$ is not $(h,s)$-length $\phi$-expanding in $G$, then some $h$-length $A$-respecting demand cannot be routed in $G$ with congestion at most $\frac{1}{2\phi}$ and dilation at most $\frac{h\cdot s}{2}$.
\end{itemize}
\end{theorem}

\section{Notations for Expander Decomposition Algorithm}\label{sec:notationsexpander}

\paragraph{Routers and expander witness.}
\begin{definition}[Routers]\label{def:routers}
Given an edge-capacitated graph $G=(V,E)$ and a node-weighting $A$ on $V$, we say that $G$ is a $t$-step $\kappa$-router for $A$ if every $A$-respecting demand can be routed in $G$ by a $t$-step flow $f$ such that for every edge $e\in E$ we have $\sum_{e\in p}f(p)\le \kappa\cdot U(e)$ flow paths in $f$. In this case, we say $f$ has \emph{edge-congestion} $\kappa$ on $G$. 

\end{definition}

 \begin{definition}[Graph Embedding]\label{def:graphEmbedding}
     An \emph{$h$-length edge-to-vertex embedding with congestion $\kappa$} from an edge-capacitated graph $H$ to $G$ with vertex lengths and capacities where $V(H)=V(G)$, is an assignment of each edge $(u,v)\in E(H)$ a flow $F_{u,v}$ on $G$ routing the demand $D(u,v)=U(u,v)$, such that $\sum_{e\in E(H)}F_e$ has length at most $h$ and congestion at most $\kappa$.
 \end{definition}
\paragraph{Length-Constrained Expansion Witnesses}

Below, for node-weighting $A$ and nodes $S$, we let $A_S$ be $A$ restricted to nodes in $S$.

\begin{definition}[Length-Constrained Expansion Witness]\label{def:LCExpWitness}
    A $(h,s)$-length $\phi$-expansion witness for graph $G$ with vertex capacities and lengths and node-weighting $A$ consists of four numbers $s_0,s_1,\kappa_0,\kappa_1$ such that $s_0 \cdot s_1 \leq s,\kappa_0 \cdot \kappa_1 \leq 1/\phi$ and the following:
    \begin{itemize}
        \item \textbf{Neighborhood Cover:} a neighborhood cover $\mcN$ of $G$ with covering radius $h$;
        \item \textbf{Routers:} an $s_0$-step $\kappa_0$-router $R_S$ of $A_S$ for each $S \in \cS\in \mcN$;
        \item \textbf{Embedding of Routers:} an $(h \cdot s_1)$-length edge-to-vertex embedding of $\cup_{S\in\cS\in\cN}R_S$ into $G$ with congestion $\kappa_1$.
    \end{itemize}
\end{definition} 

\begin{definition}[$(h,s)$-Separated Demand-Size]\label{def:demandSize}
    For a graph $G$, an $h$-length cut $C$, and a node-weighting $A$, we define the $(h,s)$-length demand-size of $C$ (with respect to $A$ on $G$) as the size of the largest $A$-respecting $h$-length demand which is $(hs)$-separated by $C$. We denote this ``demand-size'' by $A_G(h,s,C)$. When $G$ is clear from the context, we simply write $A(h,s,C)$. 
\end{definition}

\begin{definition}[Demand-Size-Largest Sparse Cut, \qLDSC]\label{def:LDSC}
    For a graph $G$, a node weighting $A$, and an $(h,s)$-length $\phi$-sparse cut $C$, we call $C$ the demand-size-largest $(h,s)$-length $\phi$-sparse cut if its demand-size is maximum among all $(h,s)$-length $\phi$-sparse cuts. We notate the size of this cut as \begin{align*}
        \qLDSC_{G,A}(\phi, h, s) := A_{G}(h,s,C)
    \end{align*}

    When $G,A$ are clear from the context, we omit them and simply write $\qLDSC(\phi,h,s)$. 
\end{definition}

\begin{restatable}[Approximately Demand-Size-Largest Sparse Cut]{definition}{apxsparsecut}\label{dfn:apxLargeCut}
    $C$ is an $\alpha$-approximate demand-size-largest $(h,s)$-length $\phi$-sparse cut for a node-weighting $A$ with length approximation $\alpha_h$, length slackness approximation $\alpha_s$ and sparsity approximation $\alpha_{\phi}$ if it is an $(\alpha_{h}\cdot h, s)$-length $\phi$-sparse cut and we have
    \begin{align*}
        A_{(h,s)}(C) \geq \frac{1}{\alpha} \cdot \qLDSC(\phi/\alpha_\phi, h/\alpha_s, s \cdot \alpha_s).
    \end{align*}
\end{restatable}


\section{Union of Sparse Vertex Moving Cut Sequence is Sparse}\label{sec:unionofspasecut}

\begin{definition}[Sequence of Moving Cuts]\label{dfn:movingCutSequence}
    Given graph $G = (V,E)$ and node-weighting $A$, a sequence of moving cuts is
    $(C_1, C_2, \ldots)$. 
    Let $G - \sum_{j < i} C_j$ denote the graph that is applied with cuts from $C_1$ to $C_{i-1}$ sequentially.    
    We refer to the $(h,s)$-length sparsity of $C_i$ with respect to $A$ in $G - \sum_{j < i} C_j$ as its $(h,s)$-length sparsity in the sequence. 
    We say the sequence $(C_1, C_2, \ldots)$ is $(h,s)$-length $\phi$-sparse if each $C_i$ is $(h,s)$-length $\phi$-sparse in the sequence.
\end{definition}

\begin{definition}[Sequence of Witnessing Demands]\label{dfn:witnessDemandSequence}
    Given graph $G = (V,E)$, a node-weighting $A$, and an $(h,s)$-length $\phi$-sparse sequence of moving cuts $(C_1, C_2, \ldots)$, we define the sequence of witnessing demands as $\mcD = (D_{1}, D_{2}, \ldots)$ such that $D_{i}$ is an $h$-length $A$-respecting demand in $G - \sum_{j < i} C_j$ and $\spa_{hs}(C_{i}, D_{i}) \le \phi$. 
    Furthermore, we assume $D_{i}$ is fully separated, i.e., $\sep_{hs}(C_{i}, D_{i}) = |D_{i}|$.
\end{definition}

\begin{restatable}[Union of Sparse Vertex Moving Cuts is a Sparse Vertex Moving Cut]{theorem}{unionOfCuts}
	\label{thm:unionOfMovingCuts} Let $(C_1, \ldots, C_k)$ be a sequence of moving cuts where $C_i$ is an $(h,s)$-length $\phi_i$-sparse cut in $G - \sum_{j < i} C_j$ w.r.t.\ node-weighting $A$. Then the moving cut $\sum_i C_i$ is an $(h',s')$-length $\phi'$-sparse cut w.r.t.\ $A$ where $h' = 2h$, $s' = \frac{(s-2)}{2}$ and $\phi' = s^3 \cdot \log^3 n \cdot n^{O(1/s)} \cdot \frac{\sum_i |C_i|}{\sum_i |C_i|/\phi_i}$.
\end{restatable}

\subsection{Application: Demand-Size-Largest Sequence of Sparse Cuts}
\begin{definition}[\qLDSCS] Fix a graph $G$, node-weighting $A$ and parameters $h$, $s$ and $\phi$. $\LDSCS$ is the demand-size of the demand-size-largest sequence of $(h,s)$-length $\phi$-sparse moving cuts. Specifically,
    \begin{align*}
        \LDSCS(\phi, h, s)  := \sum_i A_{(h,s)}(C_i)
    \end{align*}
    where above $A_{(h,s)}(C_i)$ is computed after applying all $C_j$ for $j < i$ and $(C_1, C_2, \ldots)$ is the $(h,s)$-length $\phi$-expanding moving cut sequence maximizing $\sum_i A_{(h,s)}(C_i)$.
\end{definition}

\subsection{Application: Demand-Size Largest Sparse Cut at Most Largest Expanders' Complement}
\begin{definition}[Largest Expander's Complement Size]\label{def:LEC}
    $\qLEC(\phi, h, s)$ is $\phi$ times the size of the complement of the largest $(h,s)$-length $\phi$-expanding subset of $A$. That is, let $\hat{A}$ be the $(h,s)$-length $\phi$-expanding node-weighting on $G$ satisfying $\hat{A} \preceq A$ with largest size and let $\bar{A} = A - \hat{A}$ be its complement. Then 
    \begin{align*}
        \qLEC(\phi, h, s) := \phi \cdot |\bar{A}|.
    \end{align*}\label{eqv: node weighting}
\end{definition}

\subsubsection{Largest Weighted Sparse Cut Sequence At Most Largest Cut}
\begin{definition}[Largest Weighted Sparse Cut Sequence Size]\label{def:LWSC}
    $\qLWSC(\phi, h, s)$ is the largest weighted size of a sparse cut sequence, namely
    \begin{align*}
        \qLWSC(\phi, h, s) := \sum_i \frac{\phi}{\spa_{(h,s)}(C_i,A)} \cdot |C_i|
    \end{align*}
    where $(C_1, C_2, \ldots)$ is the $(h,s)$-length $\phi$-expanding moving cut sequence maximizing $\sum_i \frac{\phi}{\spa_{(h,s)}(C_i,A)} \cdot |C_i|$ and each $\spa_{(h,s)}(C_i, A)$ is computed after applying $C_j$ for $j <i$.
\end{definition}

\begin{definition}[Largest Sparse Cut Size]\label{def:LC}
    $\qLC(\phi, h, s)$ is the size of the largest $(h,s)$-length $\phi$-sparse cut in $G$ w.r.t.\ $A$. That is 
    \begin{align*}
        \qLC(\phi, h, s) := |C_0|
    \end{align*}
    where $C_0$ is the moving cut of largest size in the set $\{C : \spa_{(h,s)}(C,A) \leq \phi \}$.
\end{definition}

\begin{restatable}{lemma}{lemLWSCAtMostLC}\label{lem:LWSCAtMostLC}
Given graph $G$ and node-weighting $A$, we have that 
\begin{align*}
\qLWSC(\phi, h, s) \leq \qLC(\phi', h', s')
\end{align*}
where $\phi' = \phi \cdot s^3 \cdot \log^3 n \cdot n^{O(1/s)}$, $h' = 2h$ and $s' = \frac{(s-2)}{2}$.
\end{restatable}

\subsubsection{Largest Cut At Most Largest Expander's Complement}
\begin{restatable}{lemma}{lemLCAtMostLEC}\label{lem:LCAtMostLEC}
Given graph $G$ and node-weighting $A$ and parameters $h,s,\phi$, we have that 
\begin{align*}
\qLC(\phi, h, s) \leq \qLEC(\phi', h, s)  
\end{align*}
where $\phi' = 3 \phi$.
\end{restatable}


\section{Approximating Demand-Size-Largest Sparse Cuts (DLSC)}\label{sec:apxDLSC}

\subsection{Constant Steps Cut Matching Games}

\paragraph{Definition.} In this section, only for the definition of a cut-matching game, we will forget about the vertex capacity and length and only consider edge-capacitated graphs $G=(V,E)$ where each edge $e\in E$ is represented as $(\text{id}_e,\text{capacity}_e)$, i.e., associated with a capacity. We define $U:E\to\bbN^+$ as the edge capacity function.

\paragraph{Cut strategies.} A cut strategy is an algorithm that is given an undirected graph $G=(V,E)$ and a node-weighting $A$, outputs a set of node-weightings pairs $\{(A^{(j)},B^{(j)})\}_j$ satisfying
\begin{enumerate}
    \item for every $j$ we have $|A^{(j)}|=|B^{(j)}|$, and $A^{(j)}+B^{(j)}\preceq A$,
    \item $A\preceq \sum_{j}(A^{(j)}+B^{(j)})$.
\end{enumerate}

\paragraph{Matching strategies.} A matching strategy is an algorithm that is given a graph $G$ and node-weighting pairs $\{(A^{(j)},B^{(j)})\}_j$, outputs for each $j$ a set of capacitated edges $M^{(j)}\subseteq \supp(A^{(j)})\times\supp(B^{(j)})$ such that for every vertex $u$ we have $U(\delta_{M^{(j)}}(u))\le A^{(j)}(u)$ and $U(\delta_{M^{(j)}}(u))\le B^{(j)}(u)$.

\paragraph{Cut-matching games.} A cut-matching game is an algorithm that is given a cut strategy and matching strategy, starts from an empty edge-capacitated graph $G_0=(V,E_0=\emptyset)$ and runs in a certain number of rounds (denoted by $r$) to update $G_0$. In the $i$-the round (starting from $i=1$), the algorithm first applies the cut strategy on the graph $G_{i-1}$ and gets a set of node-weighting pairs $\{(A^{(j)}_i,B^{(j)}_i)\}_j$. Then the algorithm applies the matching strategy on $\{(A^{(j)}_i,B^{(j)}_i)\}_j$ to get $\{M^{(j)}_i\}_j$ and get the graph $G_i=(V,E_i)$ where $E_i=E_{i-1}\bigcup\left(\cup_jM^{(j)}_i\right)$. The resulting graph of a cut-matching game is $G_r$. We care about the following parameters of a cut-matching game.

\begin{itemize}
    \item \textbf{Rounds of Interaction:} The number of rounds $r$.
    \item \textbf{Cut Batch Size:} The maximum number of pairs the cut strategy plays in each round of interaction, i.e., $\max_i |\{(A_{i}^{(j)}, B_i^{(j)})\}_j|$. The classical cut matching games can be viewed as the special case when the cut batch size is $1$. We need larger cut batch size in order to achieve constant hop.
    \item \textbf{Matching Perfectness:} If each set of edges the matching player plays for a batch always has a total capacity of at least a $1-\alpha$ fraction of the total node-weighting then we say that the cut matching game is $(1-\alpha)$-perfect. That is, a cut matching game is $(1-\alpha)$-perfect if for every $i$ we have
        \[\sum_j U\left(M_i^{(j)}\right) \geq (1-\alpha) \cdot \sum_j|A_i^{(j)}| = (1-\alpha) \cdot \sum_j|B_i^{(j)}|\]
\end{itemize}

\begin{lemma}[Cut strategy, \cite{HaeuplerHT24}]\label{lem:cut-strategy}
    For every $\eps\in\left(0,1\right)$ (possibly a function of $n$), there is a cut strategy with cut batch size $n^{O(\eps)}$ which when used in a cut matching game with $1/\eps$ rounds of interaction and an arbitrary $(1-\alpha)$-perfect matching strategy results in a $G_r$ that is a $1/\eps$-step and $n^{O(\eps)}$-router (see \Cref{def:routers}) for some $A' \preceq A$ of size $|A'| \geq (1-O(\frac{\alpha}{\eps})) \cdot |A|$. 
    This cut-strategy costs work $m\cdot n^{f(\eps)}\cdot \poly(h)$ and depth $n^{f(\eps)}\cdot\poly(h)$ where $f(\eps)\to 0$ as $\eps\to 0$.
\end{lemma}

\begin{lemma}[Application of Theorem 16.1 \cite{HaeuplerHS23}]\label{lem:matching-strategy}
    There is an algorithm that is given a graph $G=(V,E)$ with vertex capacities and length, two node-weightings $A,B\subseteq V$, length bound $h\ge 1$ and sparsity $0<\phi<1$, outputs a pair of flow and moving cut $(F,C)$ such that
    \begin{enumerate}
        \item $F$ has vertex congestion $\tO{1/\phi}$, vertex length $h$ and routes some $\hA\preceq A$ to $\tB\preceq B$.
        \item $C$ is a $h$-length vertex moving cut, $\{v\mid \hA(v)<A(v)\}$ and $\{v\mid \tB(v)<B(v)\}$ are $h$-far on $G-C$, and $C$ has size at most
        \[|C|\le \phi\cdot\left(|A|-\val(F)\right)\]
    \end{enumerate}
    The algorithm runs in $\tO{m\cdot\poly(h)}$ work and $\tO{\poly(h)}$ depth.
\end{lemma}

\subsection{Approximating DLSC from Cut-Matching Games}\label{subsec:apxDLSCcutstrategy}

\paragraph{Step 1: Create Clusters for Cut Matching Games.}\label{step:1} Apply \Cref{thm:neicov} to $G$ to compute a neighborhood cover $\cN$ with separation factor $2s$, covering radius $h_{\cov}=h/\left(\frac{1}{\eps} \cdot (2s)^{O(1/\eps)}\right)=h/s^{O(1/\eps)}$ (because $s>2$), cluster diameter $h_{\diam} = h$ and width $\omega = n^{O(\eps)}\cdot\log n$. 

\paragraph{Step 2: Run Cut Matching Games.}\label{step:2} 
First, let 
\begin{align}\label{eq:phiPrime}
    \phi' := \phi / n^{O(\eps)}
\end{align}
be the (relaxed) sparsity with respect to which we will run our cut-matching game. 

Next, we do the following for each $\cS\in\cN$. We initialize empty graph $H_S=(S,\emptyset)$ for every $S\in\cS$ and we repeat the following from $i=1$ to $1/\eps$.

\begin{enumerate}
    \item \textbf{Run cut strategies:} For each $S \in \cS$, apply the the cut strategy (from \Cref{lem:cut-strategy}) to $H_S$. Let $\{A^{(j)}_{i,S},B^{(j)}_{i,S}\}_{j\in[b]}$ be the output pairs of node-weightings from the cut strategy for cluster $S$. Here we fix $b$ to be an upper bound for the cut batch size for all cut strategies over $S\in\cS$, which satisfies $b=n^{O(\eps)}$ according to \Cref{lem:cut-strategy}. For the cut strategy that returns less than $b$ pairs of node weightings, we simply augment it to $b$ pairs by appending empty node weightings to them.
    \item \textbf{Compute a cutmatch:} For each $j\in[b]$, we apply \Cref{lem:matching-strategy} on the graph $G$, two node-weightings $A^{(j)}_{i,\cS}:=\sum_{S\in\cS}A^{(j)}_{i,S},B^{(j)}_{i,\cS}:=\sum_{S\in\cS}B^{(j)}_{i,S}$, length bound $s\cdot h_{\diam}$ and sparsity $\phi'$, to get a flow and moving cut pair $(F^{(j)}_{i,\cS},C^{(j)}_{i,\cS})$. Define $F_{i,\cS}=\cup_jF^{(j)}_{i,\cS}$

    \item \textbf{Update graphs:} For each $S\in\cS$ and each $j\in[b]$, add a matching $M^{(j)}_{i,S}\subseteq \supp(A_{i,S}^{(j)})\times \supp(B_{i,S}^{(j)})$ to $H_S$ defined as follows: $(a,b)\in M^{(j)}_{i,S}$ if there is a flow path in $F_{i,\cS}$ from $a$ to $b$, and the capacity of this edge $(a,b)$ is the summation of $F_{i,\cS}(p)$ among all flow path $p$ from $a$ to $b$.

\end{enumerate}

\paragraph{Algorithm Output.}
We return as our cut $C^*$ the union of all cuts among all $C^{(j)}_{i,\cS}$ for $j\in[b],i\in[1/\eps]$ and $\cS\in\cN$. If $C^*$ is empty, then we return a witness:
\begin{itemize}
    \item \textbf{Neighborhood Cover:} we return the neighborhood cover $\cN$ constructed in Step 1, it has covering radius $h/s^{O(1/\eps)}$;
    \item \textbf{Routers:} an $s_0$-step $\kappa_0$-router of $A_S$ for each $S \in \cS\in \mcN$, for which we return the final graph $H_S$ in the cut-matching game. Notice that $s_0=1/\eps$ and $\kappa_0=n^{O(\eps)}$ according to \Cref{lem:routers}.

    \item \textbf{Embedding of Routers:} an $(h_{\cov} \cdot s_1)$-length edge-to-vertex embedding of $\cup_{S\in\cS\in\cN}R_S$ into $G$ with congestion $\kappa_1$. We take the embedding as in Step 2 (3): every edge in $H_S=R_S$ corresponds to a flow path in $F_{i,\cS}$ for some $i,\cS$. According to \Cref{lem:matching-strategy}, these flow path has length at most $h_{\diam}\cdot s$. For the congestion, notice that for each $j\in[b]$ and $i\in[1/\eps]$, the flow $F^{(j)}_{i,\cS}$ has congestion $\tO{1/\phi'}$ according to \Cref{lem:matching-strategy}. Thus, the total congestion is at most $n^{O(\eps)}/\phi$.
    Notice that $s_1=s$ and $\kappa_1=n^{O(\eps)}/\phi$ follows from the argument above.
\end{itemize}

\begin{lemma}\label{lem:routers}
    If $C^*$ is an empty cut, then $H_S$ is a $1/\eps$-step $n^{O(\eps)}$-router.
\end{lemma}
