We start by proving the following 2 auxiliary statements:

\begin{restatable}{lemma}{LDSCSAtMostLDSC}\label{lem:LDSCSAtMostLDSC}
    Given graph $G$ and node-weighting $A$, we have that 
    \begin{align*}
    \LDSCS(\phi, h, s) \leq s^3 \cdot \log^3 n \cdot n^{O(1/s)} \cdot \LDSC(\phi', h', s')
    \end{align*}
    where $h' = 2h$, $s' = \frac{(s-2)}{2}$ and $\phi' = s^3 \cdot \log^3 n \cdot n^{O(1/s)} \cdot \phi$.
\end{restatable}
\begin{proof}
    Let $(C_1, C_2, \ldots)$ be a sequence of $(h,s)$-length $\phi$-sparse cuts such that $\sum_i A_{(h,s)}(C_i) = \qLDSCS(\phi, h, s)$ where $\phi_i \leq \phi$ is the minimum value for which $C_i$ is $\phi_i$-sparse. Let $D_1, D_2, \ldots$ be the demands witnessing these cuts so that for all $i$ we have
    \begin{align*}
        |C_i|/\phi_{i} = |D_i|.
    \end{align*}
    Let $\widehat{C} = \sum_i C_i$ where $|\widehat{C}| = \sum_{i} |C_{i}|$. 
    By \Cref{thm:unionOfMovingCuts} we know that $\widehat{C}$ is an $(h',s')$-length $\phi'$-sparse cut for $A$.
    What is more, we can further tighten the sparsity of $\widehat{C}$ by each $\phi_{i}$, and we have
    \[\spa_{(h',s')}(\widehat{C}, A) = s^3 \cdot \log^3 n \cdot n^{O(1/s)} \cdot \frac{\sum_{i} |C_{i}|}{\sum_{i}|C_{i}|/\phi_{i}},\]
    and so there must be some $h'$-length demand $D$ which is $h's'$-separated by $\widehat{C}$, and we further have
    \begin{align*}
        s^3 \cdot \log^3 n \cdot n^{O(1/s)} \cdot \frac{|\widehat{C}|}{\spa_{(h',s')}(\widehat{C}, A)} = |\widehat{C}|\cdot\frac{\sum_i |C_i|/\phi_i}{\sum_i |C_i|} = \sum_i |D_i|.
    \end{align*}
    In other words, the demand-size of $\widehat{C}$ multiplied by a sparsity slack is at least $\sum_i |D_i|$, as required.
\end{proof}

\begin{restatable}{lemma}{lemDLSCAtMostLEC}\label{lem:DLSCAtMostLEC}
    Given graph $G$ and node-weighting $A$ and parameters $h,s,\phi$, we have that 
    \begin{align*}
        \qLDSC(\phi, h, s) \leq (1/\phi)\cdot \qLEC(\phi', h', s)
    \end{align*}
    where $\phi' = \tilde{O}(\phi \cdot s^3 \cdot n^{O(1/s)})$ and $h' = 2h$.
\end{restatable}
\begin{proof}
    Let $C$ be the $(h,s)$-length $\phi$-sparse cut of largest demand-size. 
    Observe that $C$ is also a candidate for the largest weighted sparse cut sequence, and thus
    \[\frac{\phi}{\spa_{(h,s)}(C,A)}\cdot |C| = \phi \cdot \qLDSC(\phi, h, s) \leq \qLWSC(\phi, h, s)\]
    Further, by \Cref{lem:LWSCAtMostLC} we have 
    \begin{align*}
        \qLWSC(\phi, h, s) \leq \qLC(\phi', h', s')
    \end{align*}
    where $\phi' = \tilde{O}(\phi \cdot s^3 \cdot n^{O(1/s)})$, $h' = 2h$ and $s' = (s-2)/2$. Lastly, by \Cref{lem:LCAtMostLEC} we have 
    \begin{align*}
        \qLC(\phi', h', s') \leq \qLEC(3\phi', h', s').
    \end{align*}
    Combining the above and observing that $\qLEC(3\phi', h', s') \leq \qLEC(3\phi', h', s)$ gives the lemma.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}[Proof of \Cref{lem:approxsparsecut}]

Now we assume $C^*$ is not empty and we will prove that the algorithm returns an approximately demand-size-largest sparse cut. 

We first show the complexity argument.

\paragraph{Complexity.} Step 1 uses \Cref{thm:neicov}, which costs $h\cdot n^{O(\eps)}$ depth and $h\cdot n^{O(\eps)}\cdot m$ work. 

Step 2 consists of $1/\eps$ iterations. For each iteration, there are three steps.

Firstly, it simultaneously runs cut strategies for all $S\in\cS\in\cN$. Notice that according to \Cref{thm:neicov}the total number of vertices and edges for all $S\in\cS\in\cN$ are at most $n^{O(\eps)}\cdot n$ and $n^{O(\eps)}\cdot m$ because each vertex in $V$ is included in at most $n^{O(\eps)}$ many different $S$. Thus, according to \Cref{lem:cut-strategy}, all the cut-strategies in total uses depth $n^{f(\eps)}\cdot\poly(h)$ and work $m\cdot n^{f(\eps)}\cdot\poly(h)$ where $f$ is a function that goes to $0$ as $\eps$ goes to $0$.

Secondly, it simultaneously compute a cutmatch for each $j\in[b]$ and $\cS\in\cN$ by applying \Cref{lem:matching-strategy}, in total costs $\tO{m\cdot\poly(h)\cdot n^{O(\eps)}}$ work and $\tO{\poly(h)}$ depth. 

Thirdly, it updates the graphs, which is straightforward by using the computed flow, so the work and depth are subsumed by other operations. The output is by union of all the computed cut, so the cost is subsumed by other costs.

\paragraph{Correctness.} We now proceed to prove the correctness. 

The intuition for the correctness are as follows. According to \Cref{lem:LDSCSAtMostLDSC}, i.e., demand-size largest sparse cut (DLSC) is roughly at most the largest expander's complement size (LEC). Recall from \Cref{def:LEC} that largest expander's complement size (LED) is roughly less than $A-\hat{A}$ for every expanding node-weighting $\hat{A}\preceq A$. Thus, our plan is to construct a large expanding node-weighting to serve as an upper bound for DLSC, and then the demand-size of the returned cut $C^*$ will not be too smaller than that value because of the guarantee from \Cref{lem:matching-strategy}. 

For every $S\in\cS\in\cN$, let the matching perfectness of the cut-matching game on $H_S$ be $(1-\alpha_S)$. In other words, for every iteration $i$, we have $\sum_{j}U\left(M^{(j)}_{i,S}\right)\ge (1-\alpha_S)\cdot\sum_j|A^{(j)}_{i,S}|$. Moreover, there exists an iteration $i^*_S$ such that $\sum_{j}U\left(M^{(j)}_{i^*_S,S}\right)= (1-\alpha_S)\cdot\sum_j|A^{(j)}_{i^*_S,S}|$.

\paragraph{Correctness: Constructing an expanding node-weighting.} According to \Cref{lem:cut-strategy}, for every $S\in\cS\in\cN$, there exists a node-weighting $A'_S\preceq A_S$ (here $A_S$ is the node-weighting $A$ restricting to $S$) with $|A'_S|\ge (1-O(\frac{\alpha_S}{\eps}))\cdot|A|$ such that $H_S$ in the end becomes a $1/\eps$-step and $n^{O(\eps)}$-router for $A'_S$. We define $\hat{A}$ in the following way. For every node $v\in V$, if there exists $S\in\cS$ such that $A'_S(v)\le A_S(v)/2$, let $\hat{A}(v)=0$, otherwise let $\hat{A}(v)=A_S(v)$. Clearly, we have $\hA\preceq A$. We will show that $\hA$ is expanding by using \Cref{thm:flow character}.

\begin{lemma}\label{lem:expandingoftA}
    $\hA$ is $(h_{\cov},s^{O(1/\eps)})$-length $\phi/n^{O(\eps)}$-expanding on $G$.
\end{lemma}
\begin{proof}
    According to the second point of \Cref{thm:flow character}, we only need to show that, for every $h_{cov}$-length demand $D$ that is $\hA$ respecting, we can route $D$ on $G$ with congestion $n^{O(\eps)}/\phi$ and length (dilation) at most $h_{\cov}\cdot s^{O(1/\eps)}$.

    For every positive demand $D(u,v)>0$, since $\dist_G(u,v)\le h_{\cov}$, according to the definition of neighborhood cover, there exists $S\in\cS\in\cN$ such that both $u,v$ are in $S$. Moreover, since $D$ is $\hA$ respecting, we have $A'_S(v)\ge A_S(v)/2$. We route the demand $D(u,v)$ by using the $1/\eps$-step $n^{O(\eps)}$-router $H_S$ with an additional congestion factor of at most $2$ (because $D(u,v)$ can be as large as $A_S(v)$ but in the router we can only have $A'_S(v)$). We will get a routing path on $H_S$ from $u$ to $v$ and we need to map it back to the original graph $G$, this can be done by mapping each edge in $H_S$ to a path in $G$: remember that each edge in $H_S$ corresponds to a flow in step (update graphs), which according to the step (compute a cutmatch), has length bound $s\cdot h_{\diam}=s^{O(1/\eps)}\cdot h$. This gives the length bound.

    To see the total congestion, notice that every edge in $H_S$ is used at most $n^{O(\eps)}$ times, where edges in $H_S$ can be decomposed into at most $(1/\eps)\cdot b=(1/\eps)\cdot n^{O(\eps)}=n^{O(\eps)}$ (remember that $\eps>\log^{0.1}n$) matchings, each matching can be mapped to flow paths of the original graph $G$ with vertex congestion $\tO{1/\phi'}=n^{O(\eps)}/\phi$ according to the usage of \Cref{lem:matching-strategy}. Thus, routing in a single $S$ cause a total vertex congestion of $n^{O(\eps)}/\phi$ in $G$. For a single $\cS\in\cN$, it is easy to see that different routings in difference $S\in\cS$ do not share vertices with each other: every two clusters in $\cS$ are $2s\cdot h_{\diam}$-far, and remember that every flow path for the routing is $s\cdot h_{diam}$-length bounded. So we can route all the demands contributed by $\cS\in\cN$ in vertex congestion of $n^{O(\eps)}/\phi$. Notice that $|\cN|$ is the width of the neighborhood cover, bounded by $n^{O(\eps)}$, so the total vertex congestion is $n^{O(\eps)}/\phi$.
\end{proof}

According to the definition of LEC \Cref{def:LEC}, we get the following inequality from \Cref{lem:expandingoftA}.

\[LEC(\phi/n^{O(\eps)},h_{\cov},s^{O(1/\eps)})\le \left(\phi/n^{O(\eps)}\right)\cdot(|A|-|\hA|)\]

By using \Cref{lem:DLSCAtMostLEC}, we can get an upper bound for DLSC.

\begin{equation}\label{eq:DLSC}
    DLSC\left(\phi/\left(s^3\cdot n^{O(\eps+1/s)}\right),h_{\cov}/2,s^{O(1/\eps)}\right)\le \left(s^3\cdot n^{O(\eps+1/s)}\right)\cdot (|A|-|\hA|)
\end{equation}

Next, we will show the cut returned has demand-size close to $(|A|-|\hA|)$. 

\paragraph{Correctness: Returned cut is approximately demand-size-largest sparse.} We first show that the returned cut $C^*$ is sparse. In the proof we will define a demand $D$ to show the sparsity of $C^*$. $D$ will also be used later to bound the demand size of $C^*$. 

\begin{lemma}\label{lem:C*issparse}
    If $C^*$ is not empty, $C^*$ is a $(h,s)$-length $\phi$-sparse cut with respect to the node-weighting $A$.
\end{lemma}
\begin{proof}
    Recall that $C^*$ is the union of cuts $C^{(j)}_{i,\cS}$ for $j\in[b],i\in[1/\eps]$ and $\cS\in\cN$, and $C^{(j)}_{i,\cS}$ is computed from \Cref{lem:matching-strategy} which is guaranteed to satisfy

    \[|C^{(j)}_{i,\cS}|\le \phi'\cdot \left(|A^{(j)}_{i,\cS}|-\val(F^{(j)}_{i,\cS})\right)\]

    Moreover, suppose $F^{(j)}_{i,\cS}$ routes the demand $\tA^{(j)}_{i,\cS}\preceq A^{(j)}_{i,\cS}$ to $\tB^{(j)}_{i,\cS}\preceq  B^{(j)}_{i,\cS}$. Then, the two vertex sets which are not saturated by $F^{(j)}_{i,\cS}$, i.e., $V_1=\{v\mid \tA^{(j)}_{i,\cS}(v)<A^{(j)}_{i,\cS}(v)\}$ and $V_2=\{v\mid \tB^{(j)}_{i,\cS}(v)<B^{(j)}_{i,\cS}(v)\}$, they are $s\cdot h_{\diam}$-far. Thus, we can define a demand $D^{(j)}_{i,\cS}$ from $V_1$ to $V_2$ that when combined with the node-weighting saturated by $F^{(j)}_{i,\cS}$, becomes the full node-weighting $A^{(j)}_{i,\cS}$. $D^{(j)}_{i,\cS}$ is an $h_{\diam}$-length demand separated by $C^{(j)}_{i,\cS}$ and thus $C^*$, with separation length $s\cdot h_{\diam}=s \cdot h$ and demand size $\left(|A^{(j)}_{i,\cS}|-\val(F^{(j)}_{i,\cS})\right)$. We define the demand $D$ as the union of all demands $D^{(j)}_{i,\cS}$ scale down by $n^{O(\eps)}\cdot (1/\eps)=n^{O(\eps)}$ (to make sure it is $A$ respecting, because $i$ can iterate over $1/\eps$ choices and $j,\cS$ can iterate over $n^{O(\eps)}$ choices). According to the definition of sparse cut \Cref{def:sparsity}, we can give the sparsity bound of $C^*$ as (remember $h_{\diam}=h$)

    \begin{align*}
        \spa_{(h,s)}(C^*,A)&\le \frac{|C^*|}{|D|}\\
        &\le \frac{\sum_{i,j,\cS}|C^{(j)}_{i,\cS}|}{\sum_{i,j,\cS}|D^{(j)}_{i,\cS}|}\cdot n^{O(\eps)}\\
        &\le \phi'\cdot n^{O(\eps)}\\
        &\le \phi
    \end{align*}

    The third inequality comes from the fact that $|C^{(j)}_{i,\cS}|/|D^{(j)}_{i,\cS}|=|C^{(j)}_{i,\cS}|/\left(|A^{(j)}_{i,\cS}|-\val(F^{(j)}_{i,\cS})\right)\le\phi'$ for all $i,j,\cS$ from \Cref{lem:matching-strategy}.
\end{proof}

Then we bound the demand-size of $C^*$. From the proof of \Cref{lem:C*issparse}, we have already shown that $D$ is separated by $C^*$ by length $h\cdot s$. $D$ is $A$-respecting $h$-length, and has size 

\begin{equation}\label{eq:sizeofD}
    |D|=\frac{1}{n^{O(\eps)}}\cdot \sum_{i,j,\cS}|D^{(j)}_{i,\cS}|= \frac{1}{n^{O(\eps)}}\cdot \sum_{i,j,\cS}\left(\left(\sum_{S\in\cS}|A^{(j)}_{i,S}|\right)-\val(F^{(j)}_{i,\cS})\right)
\end{equation}

Recall the definition of $\hA$: a vertex $v$ has $\hA(v)<A(v)$ only happens when $\hA(v)=0$ and there exists some $S\in\cS\in\cN$ such that $A'_S(v)\le A_S(v)/2$. The definition of $A'_S$ is from \Cref{lem:cut-strategy}, i.e., an expanding sub-node-weighting of $A_S$ which has the size guarantee to be at least $(1-\frac{O(\alpha_S)}{\eps})|A_S|$ where $\alpha_S$ is the matching perfectness on the cut-matching game of $S$. Thus, every $v$ with $\hA(v)<A(v)$ contributes to the difference $\frac{O(\alpha_S)}{\eps}|A_S|$ between $|A_S|$ and $|A'_S|$ for some $S$, so we have
\[|A|-|\hA|\le \sum_{S\in\cS\in\cN}\frac{O(\alpha_S)}{\eps}|A_S|\]

According to the definition of matching perfectness, there exists an iteration $i^*_S$ for every $S$ such that $\sum_{j}U\left(M^{(j)}_{i^*_S,S}\right)= (1-\alpha_S)\cdot\sum_j|A^{(j)}_{i^*_S,S}|$, i.e., in that iteration we get

\begin{equation}\label{eq:alphas}
    \alpha_S\cdot\sum_j|A^{(j)}_{i^*_S,S}|=\sum_j|A^{(j)}_{i^*_S,S}|-\sum_{j}U\left(M^{(j)}_{i^*_S,S}\right)
\end{equation}

Recall from the definition of cut strategy that $\sum_j|A^{(j)}_{i^*_S,S}|\ge |A_S|/2$. We can take the sum over all $S$ and all iterations $i$, which gives us
\begin{align*}
    |A|-|\hA|&\le \sum_{S\in\cS\in\cN}\frac{O(\alpha_S)}{\eps}|A_S|\\
    &\le O(\frac{1}{\eps})\cdot \sum_{S\in\cS\in\cN}\alpha_S\cdot \sum_j|A^{(j)}_{i^*_S,S}|\\
    &\le^{\ref{eq:alphas}} O(\frac{1}{\eps})\cdot \sum_{S\in\cS\in\cN}\left(\sum_j|A^{(j)}_{i^*_S,S}|-\sum_{j}U\left(M^{(j)}_{i^*_S,S}\right)\right)\\
    &\le O(\frac{1}{\eps})\cdot \sum_{S\in\cS\in\cN}\sum_{i}\left(\sum_j|A^{(j)}_{i,S}|-\sum_{j}U\left(M^{(j)}_{i,S}\right)\right)\\
    &\le O(\frac{1}{\eps})\cdot \left(\sum_{i,j,S}|A^{(j)}_{i,S}|-\sum_{i,j,S}U\left(M^{(j)}_{i,S}\right)\right)\\
    &=O(\frac{1}{\eps})\cdot \left(\sum_{i,j,S}|A^{(j)}_{i,S}|-\sum_{i,j,\cS}\val\left(F^{(j)}_{i,\cS}\right)\right)
\end{align*}
\end{proof}
